package main

import (
	"io"
	"os"
	"reflect"
	"strings"
	"testing"
)

func TestMainPrintsGeneratedFiles(t *testing.T) {
	root := t.TempDir()
	for p, c := range map[string]string{
		"a.go":        "package m\n",
		"pb/x.pb.go":  "// Code generated by protoc. DO NOT EDIT.\n\npackage pb\n",
		"pb/hand.go":  "package pb\n",
		"top_gen.go":  "// Code generated by x; DO NOT EDIT.\n\npackage m\n",
		"gen_test.go": "// Code generated by x. DO NOT EDIT.\n\npackage m\n",
	} {
		full := root + "/" + p
		if err := os.MkdirAll(full[:strings.LastIndex(full, "/")], 0o750); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(full, []byte(c), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	t.Chdir(root)

	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	old := os.Stdout
	os.Stdout = w
	t.Cleanup(func() { os.Stdout = old })
	oldArgs := os.Args
	os.Args = []string{"generated", "./..."}
	t.Cleanup(func() { os.Args = oldArgs })

	main()
	w.Close()
	os.Stdout = old
	out, _ := io.ReadAll(r)

	got := strings.Fields(string(out))
	want := []string{module + "/pb/x.pb.go", module + "/top_gen.go"}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("got %q, want %q", got, want)
	}
}
